<template>
  <header class="research-nav">
    <RouterLink to="/" class="brand">≈ <span>MIROFISH</span></RouterLink>
    <nav class="desktop-links" :aria-label="$t('research.navigation')"><RouterLink to="/workbench">{{ $t('research.projects') }}</RouterLink><RouterLink to="/workbench?view=tasks">{{ $t('research.tasks') }}</RouterLink><RouterLink to="/workbench?view=demos">{{ $t('research.demos') }}</RouterLink><LanguageSwitcher /><PreferenceControls /></nav>
    <div class="nav-tools"><button type="button" class="command-toggle" @click="openSearch">{{ $t('research.quickSearch') }} <kbd>Ctrl K</kbd></button><button ref="menuToggle" class="mobile-nav-toggle" :aria-expanded="menuOpen" aria-controls="mobile-research-nav" @click="openMenu">{{ $t('research.menu') }}</button></div>
  </header>
  <div v-if="menuOpen" class="nav-backdrop" @click.self="closeMenu"><section id="mobile-research-nav" ref="menuPanel" class="mobile-panel" role="dialog" aria-modal="true" :aria-label="$t('research.navigation')" @keydown="trapFocus"><button ref="menuClose" :aria-label="$t('research.close')" @click="closeMenu">×</button><nav><RouterLink v-for="item in routes" :key="item.path" :to="item.path" @click="closeMenu">{{ $t(item.label) }}</RouterLink></nav><LanguageSwitcher /><PreferenceControls /></section></div>
  <div v-if="searchOpen" class="nav-backdrop search-backdrop" @click.self="closeSearch"><section ref="searchPanel" class="search-panel" role="dialog" aria-modal="true" aria-labelledby="command-heading" @keydown="trapFocus"><header><h2 id="command-heading">{{ $t('research.quickSearch') }}</h2><button :aria-label="$t('research.close')" @click="closeSearch">×</button></header><label for="command-query">{{ $t('research.search') }}</label><input id="command-query" ref="searchInput" v-model="query" type="search" autocomplete="off" /><p v-if="loading" role="status">{{ $t('research.loading') }}</p><p v-if="error" role="alert">{{ error }}</p><p v-if="!loading && query && !results.length">{{ $t('research.noProjects') }}</p><nav :aria-label="$t('research.projects')"><RouterLink v-for="project in results" :key="project.project_id" :to="`/workbench/${project.project_id}`" @click="closeSearch">{{ project.name }}</RouterLink></nav><nav :aria-label="$t('research.navigation')"><RouterLink v-for="item in routes" :key="item.path" :to="item.path" @click="closeSearch">{{ $t(item.label) }}</RouterLink></nav><p class="muted">{{ $t('research.safeCommands') }}</p></section></div>
</template>
<script setup>
import {nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {listProjects} from '../api/workbench'
import LanguageSwitcher from './LanguageSwitcher.vue'
import PreferenceControls from './PreferenceControls.vue'
const route=useRoute(),menuOpen=ref(false),searchOpen=ref(false),menuToggle=ref(null),menuClose=ref(null),menuPanel=ref(null),searchPanel=ref(null),searchInput=ref(null),query=ref(''),results=ref([]),loading=ref(false),error=ref('')
const routes=[{path:'/',label:'research.home'},{path:'/workbench',label:'research.projects'},{path:'/workbench?view=tasks',label:'research.tasks'},{path:'/workbench?view=demos',label:'research.demos'},{path:'/settings',label:'settings.title'}]
let returnFocus=null,searchRequest=0,debounce=null,alive=true
function openMenu(){menuOpen.value=true;nextTick(()=>menuClose.value?.focus())}
function closeMenu(){menuOpen.value=false;nextTick(()=>menuToggle.value?.focus())}
function openSearch(){returnFocus=document.activeElement;menuOpen.value=false;searchOpen.value=true;query.value='';nextTick(()=>searchInput.value?.focus());search()}
function closeSearch(){searchOpen.value=false;searchRequest++;if(debounce)clearTimeout(debounce);nextTick(()=>{if(returnFocus?.isConnected)returnFocus.focus()})}
async function search(){const token=++searchRequest;loading.value=true;error.value='';try{const data=await listProjects({q:query.value,archived:0,offset:0,limit:10});if(alive&&searchOpen.value&&token===searchRequest)results.value=data.items}catch(err){if(alive&&token===searchRequest)error.value=err.message}finally{if(alive&&token===searchRequest)loading.value=false}}
function keys(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchOpen.value?closeSearch():openSearch()}else if(event.key==='Escape'){if(searchOpen.value){event.preventDefault();closeSearch()}else if(menuOpen.value){event.preventDefault();closeMenu()}}}
function trapFocus(event){if(event.key!=='Tab')return;const panel=searchOpen.value?searchPanel.value:menuPanel.value;const items=[...panel.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),select:not(:disabled)')];const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
watch(query,()=>{if(debounce)clearTimeout(debounce);searchRequest++;debounce=setTimeout(search,180)})
watch(()=>route.fullPath,()=>{if(menuOpen.value)closeMenu();if(searchOpen.value)closeSearch()})
onMounted(()=>window.addEventListener('keydown',keys))
onUnmounted(()=>{alive=false;searchRequest++;if(debounce)clearTimeout(debounce);window.removeEventListener('keydown',keys)})
</script>
<style scoped>
.research-nav{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:16px max(24px,calc((100vw - 1320px)/2));border-bottom:1px solid var(--studio-line);background:var(--studio-surface)}.desktop-links,.nav-tools{display:flex;align-items:center;gap:16px}.brand{text-decoration:none;font-size:28px;display:flex;gap:12px;align-items:center;white-space:nowrap}.brand span{font-size:15px;letter-spacing:2px}a{color:var(--studio-ink)}button{min-height:44px;padding:8px 12px;border:1px solid var(--theme-control-line);border-radius:8px;background:var(--studio-paper);color:var(--studio-ink);font:inherit;font-size:.875rem}.mobile-nav-toggle{display:none}.nav-backdrop{position:fixed;inset:0;z-index:3100;display:flex;justify-content:flex-end;background:rgb(0 0 0 / .35)}.mobile-panel{width:min(360px,100%);height:100%;padding:24px;background:var(--studio-surface);overflow:auto}.mobile-panel>button{display:block;margin-left:auto;font-size:24px}.mobile-panel nav,.search-panel nav{display:flex;flex-direction:column;margin:20px 0;gap:6px}.mobile-panel a,.search-panel a{display:block;padding:10px 12px;border-radius:8px;text-decoration:none;overflow-wrap:anywhere}.mobile-panel a:hover,.search-panel a:hover{background:var(--studio-paper)}.search-backdrop{justify-content:center;align-items:flex-start;padding:12vh 16px 24px}.search-panel{width:min(600px,100%);max-height:75vh;overflow:auto;border:1px solid var(--studio-line);border-radius:14px;padding:24px;background:var(--studio-surface)}.search-panel header{display:flex;justify-content:space-between;align-items:center;gap:20px}.search-panel h2{font-size:1.3rem}.search-panel input{width:100%;padding:12px;border:1px solid var(--theme-control-line);border-radius:8px;background:var(--studio-paper);color:var(--studio-ink);font:inherit}.search-panel label{display:block;margin:16px 0 6px}.muted{color:var(--studio-muted);font-size:.875rem}kbd{font:.7rem var(--studio-font);padding-left:8px;color:var(--studio-muted)}@media(max-width:1100px){.research-nav{gap:16px;flex-wrap:wrap}.desktop-links{order:3;flex-basis:100%;flex-wrap:wrap;font-size:.875rem}}@media(max-width:700px){.research-nav{padding:12px 16px}.desktop-links{display:none}.mobile-nav-toggle{display:block}.nav-tools{gap:8px}kbd{display:none}.brand{gap:8px}.brand span{font-size:13px;letter-spacing:1px}.search-backdrop{padding-top:32px}.search-panel{max-height:90dvh;padding:20px}}
</style>
